select ok(not has_function_privilege('service_role','public.save_legacy_appointment(uuid,uuid,integer,jsonb,text,text)','EXECUTE'),'service role cannot bypass actor authorization through this command');
select ok(not has_function_privilege('authenticated','app_private.guard_legacy_appointment_command()','EXECUTE'),'private boundary helper is not a browser endpoint');
insert into public.roles(name) values('owner') on conflict(name) do nothing;
insert into auth.users(id,email) values('f1100000-0000-0000-0000-000000000001','legacy-staging-owner@example.invalid');
insert into public.user_roles(user_id,role_id) select 'f1100000-0000-0000-0000-000000000001',id from public.roles where name='owner';
insert into public.customers(id,display_name) values('f1200000-0000-0000-0000-000000000001','Synthetic legacy staging customer');
insert into public.service_locations(id,customer_id,street,city,state) values('f1300000-0000-0000-0000-000000000001','f1200000-0000-0000-0000-000000000001','1 Synthetic Street','Fredericksburg','VA');
insert into public.jobs(id,customer_id,service_location_id,status,requested_scope) values('f1400000-0000-0000-0000-000000000001','f1200000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000001','accepted','Synthetic legacy visit');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.save_legacy_appointment('f1500000-0000-0000-0000-000000000001','f1400000-0000-0000-0000-000000000001',null,'{"appointment_type":"job","starts_at":"2035-02-01T14:00:00Z"}','create',null)$$,'owner can create a legacy visit under the reconciled defaults');
